mapper.select:
SELECT FACTORY_CODE, PRODUCT_CODE, LOCATION_TYPE, START_DATE beginDay, END_DATE endDay, PRODUCTION_QTY planQty, COMPLETE_QTY finishQty FROM T_LH_MONTH_PLAN_SURPLUS_DETAIL WHERE IS_DELETE = 0
and year = #{year}
and month = #{month}
and factory_code = #{factoryCode}
and product_code like concat(concat('%', #{productCode}), '%')
